import '../models/models.dart';

class AnnualSecondeSvtUnit {
  final String code, title, lessonId, lessonTitle, summary, content;
  final int unitOrder;
  final List<String> keyPoints;
  final List<Exercise> exercises;
  const AnnualSecondeSvtUnit({
    required this.code, required this.unitOrder, required this.title,
    required this.lessonId, required this.lessonTitle, required this.summary,
    required this.content, required this.keyPoints, required this.exercises,
  });
  String get subjectId => code == 'a4' ? 'seconde_svt' : 'core_svt_2nde_cd';
  String get chapterId => 'core_svt_2nde_${code}_unit_$unitOrder';
}

const annualSecondeSvtUnits = <AnnualSecondeSvtUnit>[
  AnnualSecondeSvtUnit(code:'a4',unitOrder:1,title:'Les êtres vivants dans leur milieu',lessonId:'core_svt_2nde_a4_ecosystems',lessonTitle:'Étudier les êtres vivants et leurs écosystèmes',summary:'Définir biotope, biocénose, écosystème et relations trophiques.',content:'Un écosystème comprend un milieu de vie (biotope) et les êtres vivants qui l’occupent (biocénose), ainsi que leurs interactions. La biomasse est la quantité de matière vivante dans un espace donné. Au Togo, les écosystèmes comprennent notamment la savane, la forêt, la mangrove et les milieux aquatiques. Les êtres vivants entretiennent des relations : compétition, coopération, prédation et parasitisme. Une chaîne alimentaire représente le transfert de matière et d’énergie ; la flèche va de l’organisme consommé vers celui qui le consomme.',keyPoints:['Biotope : milieu physique','Biocénose : êtres vivants du milieu','Écosystème : biotope + biocénose + interactions','La flèche trophique va de la nourriture vers le consommateur'],exercises:[
    Exercise(id:'core_svt_2a4_ec1',lessonId:'core_svt_2nde_a4_ecosystems',question:'Le biotope désigne…',options:['Le milieu physique de l’écosystème','Tous les animaux uniquement','La chaîne alimentaire'],correctIndex:0,explanation:'Le biotope est l’ensemble des conditions physiques du milieu.'),
    Exercise(id:'core_svt_2a4_ec2',lessonId:'core_svt_2nde_a4_ecosystems',question:'Dans une chaîne alimentaire, la flèche indique…',options:['Le transfert de nourriture vers le consommateur','Le déplacement du vent','La taille des organismes'],correctIndex:0,explanation:'La flèche va de l’organisme consommé vers celui qui le consomme.'),
    Exercise(id:'core_svt_2a4_ec3',lessonId:'core_svt_2nde_a4_ecosystems',question:'Quel écosystème existe au Togo ?',options:['La savane','La banquise polaire','Le désert arctique'],correctIndex:0,explanation:'La savane fait partie des principaux écosystèmes du Togo.'),
  ]),
  AnnualSecondeSvtUnit(code:'a4',unitOrder:2,title:'Les équilibres naturels',lessonId:'core_svt_2nde_a4_natural_balance',lessonTitle:'Identifier les menaces et protéger l’environnement',summary:'Analyser pollution, déforestation, érosion, perte de biodiversité et mesures de protection.',content:'Les équilibres naturels peuvent être perturbés par la pollution de l’eau et de l’air, la déforestation, l’érosion des sols, les feux de brousse, le braconnage, la surpêche et le réchauffement climatique. Ces actions peuvent réduire la biodiversité et dégrader les ressources. La protection de l’environnement repose sur le traitement des eaux usées, la gestion des déchets, le reboisement, les pratiques agricoles adaptées, la protection des habitats et l’utilisation durable des ressources.',keyPoints:['Identifier les causes et effets des perturbations','Biodiversité : variété des êtres vivants','Prévention : reboisement, assainissement, gestion durable'],exercises:[
    Exercise(id:'core_svt_2a4_nb1',lessonId:'core_svt_2nde_a4_natural_balance',question:'Quel facteur peut réduire la biodiversité ?',options:['La destruction des habitats','Le reboisement','La protection des espèces'],correctIndex:0,explanation:'La destruction des habitats peut faire disparaître des espèces.'),
    Exercise(id:'core_svt_2a4_nb2',lessonId:'core_svt_2nde_a4_natural_balance',question:'Quel geste protège les sols ?',options:['Le reboisement et des pratiques culturales adaptées','La déforestation systématique','Le dépôt des déchets'],correctIndex:0,explanation:'Le reboisement et les pratiques adaptées limitent l’érosion.'),
    Exercise(id:'core_svt_2a4_nb3',lessonId:'core_svt_2nde_a4_natural_balance',question:'Pourquoi traiter les eaux usées ?',options:['Pour réduire la pollution des milieux aquatiques','Pour augmenter les déchets','Pour rendre l’eau toujours salée'],correctIndex:0,explanation:'Le traitement des eaux usées réduit les contaminants rejetés.'),
  ]),
  AnnualSecondeSvtUnit(code:'a4',unitOrder:3,title:'Nutrition minérale des plantes vertes',lessonId:'core_svt_2nde_a4_mineral_nutrition',lessonTitle:'Comprendre les besoins minéraux des plantes',summary:'Expliquer l’absorption de l’eau et des sels minéraux et leur rôle dans la croissance.',content:'Les plantes vertes absorbent l’eau et les sels minéraux du sol principalement par les racines. Les sels minéraux, notamment l’azote (N), le phosphore (P) et le potassium (K), participent à la croissance et au fonctionnement de la plante. Une carence peut ralentir le développement ; un excès d’engrais peut polluer les eaux. La germination utilise d’abord les réserves de la graine, puis la plante devient autotrophe lorsqu’elle produit sa matière organique grâce à la photosynthèse.',keyPoints:['Eau et sels minéraux absorbés par les racines','N, P et K sont des éléments minéraux importants','Éviter les carences et les excès d’engrais'],exercises:[
    Exercise(id:'core_svt_2a4_mn1',lessonId:'core_svt_2nde_a4_mineral_nutrition',question:'Par quel organe la plante absorbe-t-elle principalement l’eau du sol ?',options:['Les racines','Les fleurs','Les fruits'],correctIndex:0,explanation:'Les racines absorbent l’eau et les sels minéraux du sol.'),
    Exercise(id:'core_svt_2a4_mn2',lessonId:'core_svt_2nde_a4_mineral_nutrition',question:'Quel élément est un sel minéral essentiel ?',options:['Potassium','Plastique','Essence'],correctIndex:0,explanation:'Le potassium est un élément minéral utile à la croissance végétale.'),
    Exercise(id:'core_svt_2a4_mn3',lessonId:'core_svt_2nde_a4_mineral_nutrition',question:'Un excès d’engrais peut…',options:['Polluer les eaux','Toujours améliorer la qualité de l’eau','Supprimer les besoins des plantes'],correctIndex:0,explanation:'Les engrais en excès peuvent être entraînés vers les eaux et les polluer.'),
  ]),
  AnnualSecondeSvtUnit(code:'a4',unitOrder:4,title:'La photosynthèse',lessonId:'core_svt_2nde_a4_photosynthesis',lessonTitle:'Expliquer la photosynthèse',summary:'Relier lumière, chlorophylle, CO₂, eau et production de matière organique.',content:'La photosynthèse se déroule dans les cellules végétales contenant des chloroplastes et de la chlorophylle. En présence de lumière, la plante utilise le dioxyde de carbone de l’air et l’eau pour fabriquer des substances organiques, notamment des sucres, et libère du dioxygène. La photosynthèse transforme l’énergie lumineuse en énergie chimique stockée dans la matière organique. Elle dépend notamment de la lumière, de la chlorophylle, du CO₂, de l’eau et de la température.',keyPoints:['Lieu : chloroplastes contenant la chlorophylle','Entrées : CO₂, eau et énergie lumineuse','Produits : matière organique et dioxygène','La photosynthèse stocke l’énergie sous forme chimique'],exercises:[
    Exercise(id:'core_svt_2a4_ph1',lessonId:'core_svt_2nde_a4_photosynthesis',question:'Quel gaz la plante absorbe-t-elle pour la photosynthèse ?',options:['Dioxyde de carbone','Dioxygène uniquement','Azote pur uniquement'],correctIndex:0,explanation:'La plante utilise le dioxyde de carbone pour fabriquer de la matière organique.'),
    Exercise(id:'core_svt_2a4_ph2',lessonId:'core_svt_2nde_a4_photosynthesis',question:'Quel pigment capte l’énergie lumineuse ?',options:['La chlorophylle','L’hémoglobine','La mélanine'],correctIndex:0,explanation:'La chlorophylle absorbe une partie de l’énergie lumineuse.'),
    Exercise(id:'core_svt_2a4_ph3',lessonId:'core_svt_2nde_a4_photosynthesis',question:'Quel gaz est libéré lors de la photosynthèse ?',options:['Dioxygène','Dioxyde de carbone uniquement','Méthane'],correctIndex:0,explanation:'La photosynthèse libère du dioxygène.'),
  ]),
  AnnualSecondeSvtUnit(code:'cd',unitOrder:1,title:'L’origine et l’évolution des sols',lessonId:'core_svt_2nde_cd_soils',lessonTitle:'Décrire la formation et la dégradation des sols',summary:'Identifier les types de sols du Togo, leurs propriétés et les processus de formation.',content:'Le sol se forme lentement à partir de l’altération de la roche mère et de l’accumulation de matière organique. Il contient des particules minérales, de l’humus, de l’eau, de l’air et des êtres vivants. Ses propriétés comprennent la texture, la structure, la porosité, la perméabilité et le pH. Au Togo, on rencontre notamment des sols sableux, argileux, ferrugineux et ferralitiques. La dégradation peut être causée par l’érosion, le lessivage, la déforestation, le surpâturage et certaines pratiques agricoles. Le compostage, le reboisement et la couverture du sol contribuent à sa protection.',keyPoints:['Sol = matière minérale + matière organique + eau + air + organismes','Propriétés : texture, structure, porosité, perméabilité, pH','Le sol se forme à partir de la roche mère et de la matière organique','Protéger le sol contre l’érosion'],exercises:[
    Exercise(id:'core_svt_2cd_so1',lessonId:'core_svt_2nde_cd_soils',question:'Quel élément participe à la formation du sol ?',options:['La roche mère altérée','Le plastique seul','La lumière sans matière'],correctIndex:0,explanation:'Le sol se forme notamment par altération de la roche mère.'),
    Exercise(id:'core_svt_2cd_so2',lessonId:'core_svt_2nde_cd_soils',question:'Quel facteur peut dégrader le sol ?',options:['L’érosion','Le compostage adapté','La couverture végétale'],correctIndex:0,explanation:'L’érosion emporte les particules et dégrade le sol.'),
    Exercise(id:'core_svt_2cd_so3',lessonId:'core_svt_2nde_cd_soils',question:'Quel geste aide à protéger le sol ?',options:['Le reboisement','La déforestation','Le surpâturage'],correctIndex:0,explanation:'Le reboisement et la couverture végétale limitent l’érosion.'),
  ]),
  AnnualSecondeSvtUnit(code:'cd',unitOrder:2,title:'Stratigraphie et paléontologie',lessonId:'core_svt_2nde_cd_stratigraphy',lessonTitle:'Lire l’histoire des roches et des fossiles',summary:'Utiliser les principes stratigraphiques et les fossiles pour établir une chronologie relative.',content:'La stratigraphie étudie la succession des couches de roches. Dans une série non renversée, une couche inférieure est généralement plus ancienne qu’une couche supérieure : c’est le principe de superposition. Les fossiles sont des restes ou traces d’êtres vivants anciens conservés dans les roches. Certains fossiles permettent de comparer l’âge relatif de couches éloignées. Les principes de superposition, de continuité et de recoupement aident à reconstituer l’histoire géologique, en tenant compte des limites liées aux déformations.',keyPoints:['Superposition : couches inférieures généralement plus anciennes','Fossile : reste ou trace d’un être vivant ancien','Les fossiles aident à établir une chronologie relative','Tenir compte des déformations des couches'],exercises:[
    Exercise(id:'core_svt_2cd_st1',lessonId:'core_svt_2nde_cd_stratigraphy',question:'Dans une série non renversée, la couche la plus ancienne est généralement…',options:['La couche inférieure','La couche supérieure','Toujours au milieu'],correctIndex:0,explanation:'Le principe de superposition indique que les couches inférieures sont généralement plus anciennes.'),
    Exercise(id:'core_svt_2cd_st2',lessonId:'core_svt_2nde_cd_stratigraphy',question:'Un fossile est…',options:['Un reste ou une trace d’un organisme ancien','Une roche toujours récente','Un minéral artificiel'],correctIndex:0,explanation:'Les fossiles conservent des restes ou traces d’êtres vivants anciens.'),
    Exercise(id:'core_svt_2cd_st3',lessonId:'core_svt_2nde_cd_stratigraphy',question:'La stratigraphie permet notamment…',options:['De reconstituer une chronologie relative','De mesurer la température de l’air','De calculer le poids d’un objet'],correctIndex:0,explanation:'La stratigraphie aide à établir l’ordre relatif des formations géologiques.'),
  ]),
  AnnualSecondeSvtUnit(code:'cd',unitOrder:3,title:'Organisation de la cellule',lessonId:'core_svt_2nde_cd_cell',lessonTitle:'Décrire l’organisation d’une cellule',summary:'Identifier membrane, cytoplasme, noyau et organites principaux.',content:'La cellule est l’unité de base des êtres vivants. Une cellule eucaryote possède une membrane plasmique, un cytoplasme et un noyau contenant l’information génétique. Elle contient aussi des organites qui assurent des fonctions particulières. Les cellules végétales possèdent notamment une paroi, une grande vacuole et, dans les cellules chlorophylliennes, des chloroplastes. Les cellules spécialisées ont des formes et fonctions adaptées.',keyPoints:['La cellule est l’unité de base du vivant','Membrane, cytoplasme et noyau','Cellule végétale : paroi, vacuole, chloroplastes selon le type'],exercises:[
    Exercise(id:'core_svt_2cd_ce1',lessonId:'core_svt_2nde_cd_cell',question:'Quel élément contient l’essentiel de l’information génétique dans une cellule eucaryote ?',options:['Le noyau','La paroi','La vacuole seulement'],correctIndex:0,explanation:'Le noyau contient les chromosomes et l’information génétique.'),
    Exercise(id:'core_svt_2cd_ce2',lessonId:'core_svt_2nde_cd_cell',question:'Quel organite réalise la photosynthèse dans une cellule végétale ?',options:['Le chloroplaste','Le ribosome uniquement','Le noyau'],correctIndex:0,explanation:'Les chloroplastes contiennent la chlorophylle et sont le siège de la photosynthèse.'),
    Exercise(id:'core_svt_2cd_ce3',lessonId:'core_svt_2nde_cd_cell',question:'La membrane plasmique…',options:['Délimite la cellule et contrôle les échanges','Fabrique les roches','Remplace le noyau'],correctIndex:0,explanation:'La membrane délimite la cellule et régule les échanges avec le milieu.'),
  ]),
  AnnualSecondeSvtUnit(code:'cd',unitOrder:4,title:'Division cellulaire et mitose',lessonId:'core_svt_2nde_cd_mitosis',lessonTitle:'Comprendre la mitose et la conservation des chromosomes',summary:'Décrire les étapes principales de la division cellulaire.',content:'La mitose permet à une cellule de donner deux cellules filles génétiquement identiques, dans les conditions normales. Avant la division, l’ADN est répliqué. Les chromosomes se condensent, s’alignent au centre, puis les chromatides sœurs se séparent vers les pôles. La cellule se divise ensuite. La mitose contribue à la croissance, au renouvellement et à la réparation des tissus. Le nombre de chromosomes est conservé dans les cellules filles.',keyPoints:['L’ADN est répliqué avant la mitose','Les chromatides sœurs se séparent','Deux cellules filles sont produites','Le nombre de chromosomes est conservé'],exercises:[
    Exercise(id:'core_svt_2cd_mi1',lessonId:'core_svt_2nde_cd_mitosis',question:'Quel événement précède la mitose ?',options:['La réplication de l’ADN','La disparition de tous les chromosomes','La formation d’un fossile'],correctIndex:0,explanation:'L’ADN est répliqué avant la division cellulaire.'),
    Exercise(id:'core_svt_2cd_mi2',lessonId:'core_svt_2nde_cd_mitosis',question:'La mitose produit normalement…',options:['Deux cellules filles','Quatre cellules filles directement','Une cellule sans ADN'],correctIndex:0,explanation:'La mitose produit deux cellules filles.'),
    Exercise(id:'core_svt_2cd_mi3',lessonId:'core_svt_2nde_cd_mitosis',question:'Après la mitose, le nombre de chromosomes des cellules filles…',options:['Est conservé','Double toujours','Devient zéro'],correctIndex:0,explanation:'La mitose conserve le nombre de chromosomes.'),
  ]),
  AnnualSecondeSvtUnit(code:'cd',unitOrder:5,title:'Nutrition minérale des plantes',lessonId:'core_svt_2nde_cd_plant_nutrition',lessonTitle:'Relier l’absorption minérale à la croissance',summary:'Expliquer l’absorption de l’eau et des sels minéraux et leur transport.',content:'Les racines absorbent l’eau et les ions minéraux de la solution du sol. Les poils absorbants augmentent la surface d’échange. L’eau et les sels minéraux constituent la sève brute, transportée des racines vers les feuilles par les vaisseaux du xylème. Les éléments minéraux, notamment N, P et K, sont nécessaires à la croissance. Une concentration trop faible ou trop élevée peut perturber le développement ; l’utilisation des engrais doit être raisonnée.',keyPoints:['Poils absorbants : surface d’échange','Sève brute : eau et sels minéraux','Xylème : transport vers les feuilles','N, P, K participent à la croissance'],exercises:[
    Exercise(id:'core_svt_2cd_pn1',lessonId:'core_svt_2nde_cd_plant_nutrition',question:'Que contient la sève brute ?',options:['Eau et sels minéraux','Sucres uniquement','Air uniquement'],correctIndex:0,explanation:'La sève brute transporte l’eau et les sels minéraux absorbés par les racines.'),
    Exercise(id:'core_svt_2cd_pn2',lessonId:'core_svt_2nde_cd_plant_nutrition',question:'Quel tissu transporte la sève brute ?',options:['Le xylème','Le muscle','La peau'],correctIndex:0,explanation:'Le xylème transporte la sève brute vers les parties aériennes.'),
    Exercise(id:'core_svt_2cd_pn3',lessonId:'core_svt_2nde_cd_plant_nutrition',question:'Pourquoi faut-il éviter l’excès d’engrais ?',options:['Il peut perturber la plante et polluer les eaux','Il ne contient jamais de minéraux','Il remplace la lumière'],correctIndex:0,explanation:'Un excès d’engrais peut nuire à la plante et entraîner une pollution.'),
  ]),
  AnnualSecondeSvtUnit(code:'cd',unitOrder:6,title:'Équilibres naturels et changement climatique',lessonId:'core_svt_2nde_cd_environment',lessonTitle:'Analyser les déséquilibres de l’environnement',summary:'Identifier les causes et conséquences des changements environnementaux.',content:'Les écosystèmes sont perturbés par la pollution, la déforestation, la perte de biodiversité, l’érosion des sols et les changements climatiques. L’effet de serre naturel maintient une température favorable à la vie, mais l’augmentation de certains gaz liée aux activités humaines renforce le réchauffement. Les mesures de protection comprennent la réduction des émissions, la conservation des habitats, le reboisement, la gestion durable des ressources et l’adaptation aux risques.',keyPoints:['L’effet de serre naturel est nécessaire à la vie','Les émissions supplémentaires renforcent le réchauffement','Préserver habitats et biodiversité','Réduire pollution et dégradation des sols'],exercises:[
    Exercise(id:'core_svt_2cd_en1',lessonId:'core_svt_2nde_cd_environment',question:'Qu’est-ce qui renforce le réchauffement climatique actuel ?',options:['L’augmentation de certains gaz à effet de serre due aux activités humaines','La disparition de tous les gaz','La rotation de la Terre uniquement'],correctIndex:0,explanation:'Les émissions humaines de gaz à effet de serre renforcent l’effet de serre.'),
    Exercise(id:'core_svt_2cd_en2',lessonId:'core_svt_2nde_cd_environment',question:'Quel geste contribue à protéger la biodiversité ?',options:['Préserver les habitats naturels','Détruire les forêts','Polluer les cours d’eau'],correctIndex:0,explanation:'La protection des habitats aide à préserver les espèces.'),
    Exercise(id:'core_svt_2nde_cd_en3',lessonId:'core_svt_2nde_cd_environment',question:'Quel est un exemple de gestion durable ?',options:['Utiliser les ressources sans compromettre leur renouvellement','Épuiser toutes les ressources immédiatement','Ignorer les impacts'],correctIndex:0,explanation:'La gestion durable vise à préserver les ressources à long terme.'),
  ]),
];

final annualSecondeCdSvtSubject = Subject(
  id:'core_svt_2nde_cd',name:'SVT — Seconde C & D',iconName:'leaf',
  colorHex:'2E7D32',level:SchoolLevel.seconde,track:SchoolTrack.scientific,
  totalChapters:6,
);

final annualSecondeSvtChapters = annualSecondeSvtUnits.map((unit) => Chapter(
  id:unit.chapterId,subjectId:unit.subjectId,title:'Unité ${unit.unitOrder} — ${unit.title}',
  order:unit.unitOrder,term:unit.unitOrder,totalLessons:1,
)).toList();

final annualSecondeSvtLessons = annualSecondeSvtUnits.map((unit) => Lesson(
  id:unit.lessonId,chapterId:unit.chapterId,title:unit.lessonTitle,
  summary:unit.summary,content:unit.content,keyPoints:unit.keyPoints,durationMinutes:25,
)).toList();

final annualSecondeSvtExercises = annualSecondeSvtUnits.expand((unit)=>unit.exercises).toList();
